        Controls.Add(_statusStrip);
    }

    // .NET 9 breaking change: DropDownControl now throws ArgumentNullException if passed null.
    // Guard against null before calling.
    public void ShowDropDown(IWindowsFormsEditorService editorService, Control control)
    {
        if (control is not null)
        {
            editorService.DropDownControl(control);
        }
    }

    // .NET 9 breaking change: GenerateProgIdForType removed from Marshal.
    // Use Type.GUID and registry lookup or a custom attribute instead.
    public static string GetProgId(Type comType)
    {
        var progIdAttr = (ProgIdAttribute?)Attribute.GetCustomAttribute(comType, typeof(ProgIdAttribute));
        return progIdAttr?.Value ?? comType.FullName!;
    }

    // P/Invoke declarations use LibraryImportAttribute (source-generated) on .NET 9+
    [LibraryImport("user32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static partial bool ShowWindow(IntPtr hWnd, int nCmdShow);
}

